export function connectionActions(p,id){return {
    'mailbox-oauth-config':()=>['GET','/v1/mailboxes/oauth/config'],
    'mailbox-oauth-start':()=>['POST','/v1/mailboxes/oauth/start',p.input],
    'mailbox-oauth-status':()=>['GET',`/v1/mailboxes/oauth/${id(p.sessionId)}`],
    'mailbox-oauth-complete':()=>['POST',`/v1/mailboxes/oauth/${id(p.sessionId)}/complete`,{mailboxId:p.mailboxId}],
    'mailbox-disconnect':()=>['POST',`/v1/accounts/${id(p.accountId)}/mailbox-disconnect`,{reason:p.reason}],
    'mailbox-info':()=>['GET',`/v1/accounts/${id(p.accountId)}/mailbox-info`],
    'draft-upload-start':()=>['POST',`/v1/accounts/${id(p.accountId)}/draft-uploads`,p.input],
    'draft-upload-status':()=>['GET',`/v1/accounts/${id(p.accountId)}/draft-uploads/${id(p.uploadId)}`],
    'draft-upload-chunk':()=>['PUT',`/v1/accounts/${id(p.accountId)}/draft-uploads/${id(p.uploadId)}`,{index:p.index,data:p.data}],
    'draft-upload-complete':()=>['POST',`/v1/accounts/${id(p.accountId)}/draft-uploads/${id(p.uploadId)}/complete`,{}],
    'draft-upload-cancel':()=>['DELETE',`/v1/accounts/${id(p.accountId)}/draft-uploads/${id(p.uploadId)}`],
    'inbox-replies':()=>['GET',`/v1/inbox/threads/${id(p.threadId)}/replies`],
    'inbox-reply-prepare':()=>['POST',`/v1/inbox/threads/${id(p.threadId)}/replies/prepare`,{text:p.text,...(p.idempotencyKey?{idempotencyKey:p.idempotencyKey}:{})}],
    'social-login-start':()=>['POST','/v1/social/connections',p.input],
    'social-login-list':()=>['GET','/v1/social/connections'],
    'social-login-get':()=>['GET',`/v1/social/connections/${id(p.sessionId)}`],
    'social-login-check':()=>['POST',`/v1/social/connections/${id(p.sessionId)}/check`,{}],
    'social-login-open':()=>['POST',`/v1/social/connections/${id(p.sessionId)}/open`,{}],
    'social-login-confirm':()=>['POST',`/v1/social/connections/${id(p.sessionId)}/confirm`,p.input],
    'social-login-cancel':()=>['POST',`/v1/social/connections/${id(p.sessionId)}/cancel`,{}],
    'social-login-pause':()=>['POST',`/v1/social/connections/${id(p.sessionId)}/pause`,{}],
    'social-login-resume':()=>['POST',`/v1/social/connections/${id(p.sessionId)}/resume`,{}],
    'account-qualify':()=>['POST',`/v1/accounts/${id(p.accountId)}/qualify`,p.input??{}],
    'account-disconnect':()=>['POST',`/v1/accounts/${id(p.accountId)}/disconnect`,p.input],
};}
